/* 在已打开的全新原型页面内执行；只操作演示数据。 */
(async () => {
  const results=[];
  const node=s=>document.querySelector(s);
  const assert=(name,condition)=>{results.push({name,passed:!!condition});if(!condition)throw new Error(name);};
  const click=s=>node(s).click();
  const type=text=>{node('#reply').value=text;node('#reply').dispatchEvent(new Event('input',{bubbles:true}));};
  const closeDialog=action=>new Promise(resolve=>{node('#dialog').addEventListener('close',resolve,{once:true});action();});
  assert('初始空回复不可发送',node('#send').disabled);
  click('input[value="core"]');click('input[value="inbox"]');
  assert('单选始终只保留一项',document.querySelectorAll('#options input:checked').length===1);
  type('回归测试：保留第一个草稿');
  click('button[data-task="demo-002"]');type('回归测试：第二个草稿');
  click('input[value="report"]');click('input[value="charts"]');
  assert('多选保留两项',document.querySelectorAll('#options input:checked').length===2);
  click('button[data-task="demo-001"]');
  assert('草稿按请求隔离',node('#reply').value==='回归测试：保留第一个草稿');
  click('#later');assert('稍后处理不结束请求',!node('#send').disabled);
  node('#reply').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',ctrlKey:true,isComposing:true,bubbles:true}));
  assert('输入法组合期间不发送',!node('#send').disabled&&!node('#reply').readOnly);
  click('button[data-task="demo-003"]');
  assert('断线禁止提交',node('#send').disabled&&node('#reply').readOnly);
  click('button[data-task="demo-002"]');click('#decline');await closeDialog(()=>click('button[value="cancel"]'));
  assert('取消拒绝对话框不改变请求',!node('#send').disabled);
  click('#decline');await closeDialog(()=>click('#dialog-confirm'));
  assert('确认拒绝显示独立结果',node('#state-notice').textContent.includes('明确拒绝'));
  click('button[data-task="demo-001"]');click('#decline');await closeDialog(()=>node('#dialog').close());
  assert('上次确认不泄漏至下次关闭',!node('#send').disabled);
  click('#send');assert('发送后不能重复发送',node('#send').disabled&&node('#state-notice').textContent.includes('没有真实投递'));
  click('#filter-done');assert('已处理包含两条记录',document.querySelectorAll('.task').length===2);
  click('#focus-mode');assert('聚焦收起侧栏',getComputedStyle(node('.sidebar')).display==='none');click('#focus-mode');
  assert('视口无横向溢出',document.documentElement.scrollWidth<=innerWidth);
  return {total:results.length,passed:results.filter(r=>r.passed).length,results};
})();
